    @Test
    void sieveCountsTwentyFivePrimesBelowHundred() {
        // flags at address 1024..1123 (1 = composite); count the zeros for 2..99
        RunResult r = boot("""
            li s0, 1024        # base
            li s1, 100         # N
            li t0, 2           # i
            outer: bge t0, s1, count
              add t1, s0, t0
              lbu t2, 0(t1)
              bnez t2, next
              mul t3, t0, t0   # j = i*i
            inner: bge t3, s1, next
              add t4, s0, t3
              li t5, 1
              sb t5, 0(t4)
              add t3, t3, t0
              j inner
            next: addi t0, t0, 1
              j outer
            count: li t0, 2
              li a0, 0
            cl: bge t0, s1, fin
              add t1, s0, t0
              lbu t2, 0(t1)
              bnez t2, skip
              addi a0, a0, 1
            skip: addi t0, t0, 1
              j cl
            fin: li a7, 93
              ecall
            """, 2048).run(1_000_000);
        assertEquals(Halt.EXIT, r.halt());
        assertEquals(25, r.exitCode());
    }

    @Test
    void bubbleSortInMemory() {
        Cpu c = boot("""
            li s0, 512
            li s1, 8
            # store 8 values: 5, -3, 9, 0, 9, -8, 2, 7
            li t0, 5
            sw t0, 0(s0)
            li t0, -3
            sw t0, 4(s0)
            li t0, 9
            sw t0, 8(s0)
            sw x0, 12(s0)
            sw t0, 16(s0)
            li t0, -8
            sw t0, 20(s0)
            li t0, 2
            sw t0, 24(s0)
            li t0, 7
            sw t0, 28(s0)
            li t0, 0            # pass counter
            pass: addi t6, s1, -1
              bge t0, t6, end
              li t1, 0
            cmp: sub t2, t6, t0
              bge t1, t2, nextpass
              slli t3, t1, 2
              add t3, t3, s0
              lw t4, 0(t3)
              lw t5, 4(t3)
              ble t4, t5, noswap
              sw t5, 0(t3)
              sw t4, 4(t3)
            noswap: addi t1, t1, 1
              j cmp
            nextpass: addi t0, t0, 1
              j pass
            end: ebreak
            """, 1024);
        RunResult r = c.run(100_000);
        assertEquals(Halt.BREAK, r.halt());
        int[] expected = {-8, -3, 0, 2, 5, 7, 9, 9};
        for (int k = 0; k < 8; k++) {
            assertEquals(expected[k], c.memWord(512 + 4 * k), "slot " + k);
        }
    }

    @Test
    void recursiveFactorialUsesTheStack() {
        RunResult r = boot("""
            li a0, 10
            jal ra, fact
            li a7, 93
            ecall
            fact: li t0, 2
              blt a0, t0, base
              addi sp, sp, -8
              sw ra, 4(sp)
              sw a0, 0(sp)
              addi a0, a0, -1
              jal ra, fact
              lw t1, 0(sp)
              lw ra, 4(sp)
              addi sp, sp, 8
              mul a0, a0, t1
              ret
            base: li a0, 1
              ret
            """, 512).run(10_000);
        assertEquals(3628800, r.exitCode());
    }

